const config = $input.first().json;
const owner = typeof config.owner === 'string' ? config.owner.trim() : '';
const repo = typeof config.repo === 'string' ? config.repo.trim() : '';
if (!/^[A-Za-z0-9-]+$/.test(owner) || !/^[A-Za-z0-9_.-]+$/.test(repo) || repo === '.' || repo === '..') {
  throw new Error('Укажите отдельные имена owner и repo');
}
const email = typeof config.email === 'string' ? config.email.trim() : '';
const [local, domain, extra] = email.split('@');
const localPattern = /^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*$/;
const domainPattern = /^(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+(?:[A-Za-z]{2,63}|xn--[A-Za-z0-9-]{1,58}[A-Za-z0-9])$/;
if (extra !== undefined || !domain || email.length > 254 ||
    local.length > 64 || !localPattern.test(local) || !domainPattern.test(domain)) {
  throw new Error('Передайте корректный email получателя');
}
return [{json: {owner, repo, email}}];

const stats = $input.first().json;
const from = new Date(stats.period?.from);
const to = new Date(stats.period?.to);
const names = ['created', 'closed', 'updated', 'needsTriage'];
if (!stats.repository || !stats.period?.text || !(to > from) || !Array.isArray(stats.rows) ||
    !names.every(name => Number.isSafeInteger(stats.counts?.[name]) && stats.counts[name] >= 0)) {
  throw new Error('Sub-workflow не вернул статистику в ожидаемом формате');
}
const dateParts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Moscow', year: 'numeric', month: '2-digit', day: '2-digit',
}).formatToParts(to);
const date = Object.fromEntries(dateParts.map(({type, value}) => [type, value]));
const monday = new Date(Date.UTC(+date.year, +date.month - 1, +date.day));
monday.setUTCDate(monday.getUTCDate() - (monday.getUTCDay() + 6) % 7);
const week_key = monday.toISOString().slice(0, 10);
monday.setUTCDate(monday.getUTCDate() - 7);
const previous_week = monday.toISOString().slice(0, 10);
const repository = stats.repository.toLowerCase();
const snapshot = {
  repository, week_key, period_from: from.toISOString(), period_to: to.toISOString(),
  created: stats.counts.created, closed: stats.counts.closed,
  updated: stats.counts.updated, needs_triage: stats.counts.needsTriage,
};
return [{json: {stats, snapshot, previous_week}}];

const {stats, snapshot, previous_week} = $('Подготовить сводку').first().json;
const row = $input.first().json;
const metrics = ['created', 'closed', 'updated', 'needs_triage'];
const previous = row.week_key === previous_week && row.repository === snapshot.repository
  ? Object.fromEntries(metrics.map(key => [key, row[key]]))
  : null;
if (previous && !metrics.every(key => Number.isSafeInteger(previous[key]) && previous[key] >= 0)) {
  throw new Error('Проверьте числовые поля в сводке прошлой недели');
}
const current = Object.fromEntries(metrics.map(key => [key, snapshot[key]]));
const changes = previous
  ? Object.fromEntries(metrics.map(key => [key, current[key] - previous[key]]))
  : null;
return [{json: {stats, snapshot, comparison: {current, previous, changes}}}];

const {stats, comparison} = $('Посчитать изменения').first().json;
const output = $input.first().json.text;
const commentary = typeof output === 'string' && output.trim()
  ? output.trim()
  : 'AI-комментарий недоступен.';
const formatChange = key => {
  const count = comparison.current[key];
  if (!comparison.changes) return String(count);
  const change = comparison.changes[key];
  return count + ' (' + (change > 0 ? '+' : '') + change + ')';
};
const escapeHtml = value => String(value).replace(/[&<>"']/g, character => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
}[character]));
if (!stats.period?.text || !stats.counts || !Array.isArray(stats.rows)) {
  throw new Error('Sub-workflow не вернул статистику в ожидаемом формате');
}
const body = stats.rows.length
  ? stats.rows.map(row => '<tr><td>' + escapeHtml(row.type) +
      '</td><td>' + escapeHtml(row.author) + '</td><td>' +
      Number(row.count) + '</td></tr>').join('')
  : '<tr><td colspan="3">Новых Issues за неделю нет</td></tr>';
const html = '<!doctype html><html lang="ru"><body>' +
  '<h2>Issues за ' + escapeHtml(stats.period.text) + '</h2>' +
  '<p>Репозиторий: ' + escapeHtml(stats.repository) + '</p>' +
  '<p>Создано: ' + formatChange('created') + '; закрыто: ' + formatChange('closed') +
  '; обновлено: ' + formatChange('updated') +
  '; новых с needs-triage: ' + formatChange('needs_triage') + '.</p>' +
  (comparison.changes ? '' : '<p>Нет данных для сравнения с прошлой неделей.</p>') +
  '<table border="1" cellpadding="6" cellspacing="0">' +
  '<thead><tr><th>Тип</th><th>Автор</th><th>Количество</th></tr></thead>' +
  '<tbody>' + body + '</tbody></table>' +
  '<h3>AI-комментарий недели</h3><p>' + escapeHtml(commentary) + '</p></body></html>';
return [{json: {subject: 'Еженедельная статистика Issues — ' + stats.period.text, html}}];
